async function main() {
  const args = argv.slice(2);
  if (args.length === 0) {
    console.log(USAGE);
    return 0;
  }

  let flags;
  let rest;
  try {
    ({ flags, rest } = parseFlags(args));
  } catch (err) {
    console.error(`loop-development: ${err.message}\n\n${USAGE}`);
    return 1;
  }

  if (flags.help) {
    console.log(USAGE);
    return 0;
  }
  if (flags.version) {
    const pkg = await readPackageJson();
    console.log(pkg.version);
    return 0;
  }
  if (flags.listPresets) {
    printPresets();
    return 0;
  }

  const command = rest[0];
  try {
    switch (command) {
      case "init":
        return await runInit(flags, rest);
      case "update":
        return await runUpdate(flags);
      case "uninstall":
        return await runUninstall(flags);
      case "skills":
        return await runSkills(rest, flags);
      case "rules":
        return await runRules(rest, flags);
      case "status":
        await status({ configDir: flags.configDir });
        return 0;
      case "doctor":
        return await runDoctor(flags);
      case "set-model":
        return await runSetModel(rest, flags);
      case "set-mode":
        return await runSetMode(rest, flags);
      case "models":
        return await runModels(flags);
      case "migrate":
        return await runMigrate(rest, flags);
      case "architecture":
        return await runArchitecture(rest, flags);
      case "secrets":
        return await runSecrets(rest, flags);
      case "telegram":
        return await runTelegram(rest, flags);
      case "allow":
        return await runAllow(rest, flags);
      case "link":
        return await runLink(rest, flags);
      case "unlink":
        return await runUnlink(rest, flags);
      default:
        console.error(`loop-development: comando desconhecido "${command}"\n\n${USAGE}`);
        return 1;
    }
  } catch (err) {
    console.error(`loop-development: ${err.message}`);
    return 1;
  }
}

main().then((code) => process.exitCode = code);

#!/usr/bin/env node
// Gatilho npm `prepare`. Garante que as dependências de verificação (typecheck,
// testes) estão instaladas, instalando-as em falta.
//
// Nunca falha a instalação: um ambiente offline, sem rede ou sem permissões não
// pode impedir o utilizador de instalar o pacote. Por isso o exit code é sempre
// 0 e os problemas são apenas reportados.
import { fileURLToPath } from "node:url";
import { dirname } from "node:path";
import { ensureDeps } from "../src/deps.js";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const log = (message) => console.log(`[deps] ${message}`);

try {
  const result = await ensureDeps({ cwd: root, fix: true, log });
  if (result.isDevCheckout && result.missing.length > 0) {
    console.warn(`[deps] ainda em falta: ${result.missing.join(", ")}`);
  }
  if (result.isDevCheckout && result.undeclared.length > 0) {
    console.warn(`[deps] não declaradas no package.json: ${result.undeclared.join(", ")}`);
  }
} catch (err) {
  console.warn(`[deps] verificação de dependências falhou: ${err.message}`);
}

process.exitCode = 0;
